477. {
478.     public static readonly IReadOnlyDictionary<string, double> Values = new Dictionary<string, double>
479.     {
480.         ["TokenReduction"] = 0.05,
481.         ["ToolCallReduction"] = 0.025,
482.         ["TaskCompletionImprovement"] = 0.15,
483.         ["TimeReduction"] = 0.025,
